INSERT INTO custom_templates
  (id, nombre, tagline, rubros, tags, accent, image, image_fallback, sections, demo, seeds, text_styles, published, palette_override, created_by)
VALUES (
  'manos-de-barro',
  'Manos de Barro',
  'Para talleres artesanales y cooperativas de oficios: catálogo con filtro por material, proceso productivo y ferias donde encontrarte.',
  '["comercio"]'::jsonb,
  '["comercio","artesanias","ceramica","telar","madera","hecho-a-mano","diseño"]'::jsonb,
  '#b5502f',
  'https://d38e2ri338t20n.cloudfront.net/uploads/7f1d2b79-d690-4dc7-ae45-15669564a93e.jpg',
  'https://d38e2ri338t20n.cloudfront.net/uploads/7f1d2b79-d690-4dc7-ae45-15669564a93e.jpg',
  $manosbarro$[{"type":"header","variant":"clasico"},{"type":"hero","variant":"flanqueada","rubroLabel":"Taller colectivo · Córdoba, Argentina","titulo":"Piezas hechas a mano, una por vez.","descripcion":"Cerámica, telar y madera trabajados por tres artesanas en un taller compartido. Nada en serie, nada apurado.","stats":[{"value":"3","label":"artesanas"},{"value":"340+","label":"piezas al año"},{"value":"100%","label":"hecho a mano"}],"botones":{"primary":{"funcion":"seccion","label":"Ver las piezas"},"secondary":{"funcion":"seccion","label":"Ver ferias"}}},{"type":"productos","variant":"destacada","titulo":"Piezas disponibles"},{"type":"proceso-taller","eyebrow":"El proceso","titulo":"De la materia cruda a tu casa","pasos":[{"id":"proceso-1","titulo":"Buscamos la materia","desc":"Arcilla de cantera cercana, lana de productores de la zona y madera de descarte de aserraderos.","imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/8892862b-8ea7-4869-96cb-fa1088145572.jpg"},{"id":"proceso-2","titulo":"Trabajo de taller","desc":"Torno, telar de pie y banco de carpintería. Todo a mano, sin moldes ni producción en serie.","imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/256283de-8bc1-4517-9899-45ec39a4ecb3.jpg"},{"id":"proceso-3","titulo":"Color y terminación","desc":"Esmaltes propios y tintes vegetales que preparamos en el taller, tanda por tanda.","imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/b93bc827-4acd-4b4b-a1ca-fcdd55fc9c8e.jpg"},{"id":"proceso-4","titulo":"Listo para tu mesa","desc":"Revisamos cada pieza, la firmamos por debajo y la embalamos en papel y cartón reciclado.","imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/238a2bcf-4605-46f5-94f7-e9577e47fa72.jpg"}]},{"type":"artesanas","titulo":"Quiénes hacen las piezas","artesanas":[{"id":"artesana-1","nombre":"Rosa Giraldo","oficio":"Cerámica","anios":"22 años","bio":"Aprendió con su abuela en Traslasierra. Trabaja al torno y quema en horno a leña dos veces por mes.","firma":"Sello de barro en la base","badgeBg":"#b5502f"},{"id":"artesana-2","nombre":"Amparo Quiroga","oficio":"Telar","anios":"15 años","bio":"Hila, tiñe y teje. Sus mantas llevan entre cuatro y ocho semanas de telar según el tamaño.","firma":"Etiqueta de lino cosida","badgeBg":"#6b7f5e"},{"id":"artesana-3","nombre":"Bruno Salas","oficio":"Madera","anios":"18 años","bio":"Recupera algarrobo y quebracho de aserraderos y los devuelve como tablas, bandejas y bancos.","firma":"Iniciales a fuego","badgeBg":"#8a6a3f"}]},{"type":"ferias","titulo":"Dónde encontrarnos","subtitulo":"Ferias y mercados · 2026","ferias":[{"id":"feria-1","fechas":"14—16 AGO","nombre":"Feria de Diseño Cordobés","ciudad":"Paseo del Buen Pastor, Córdoba","stand":"B-12","destacada":true},{"id":"feria-2","fechas":"05—07 SEP","nombre":"Mercado de Artesanas","ciudad":"Villa General Belgrano","stand":"A-04","destacada":false},{"id":"feria-3","fechas":"18—20 OCT","nombre":"Encuentro de Telar y Barro","ciudad":"Alta Gracia","stand":"C-21","destacada":false},{"id":"feria-4","fechas":"29 NOV—01 DIC","nombre":"Feria Navideña de Oficios","ciudad":"Parque Sarmiento, Córdoba","stand":"D-08","destacada":false}]},{"type":"citas-rotativas","eyebrow":"Nos escriben","citas":[{"id":"cita-1","frase":"Compré un bowl en la feria y volví por el juego completo. Se nota que cada pieza pasó por unas manos.","persona":"Marina Paz","ciudad":"Córdoba"},{"id":"cita-2","frase":"Encargué una manta para regalar y me mandaron fotos del telar mientras la tejían. Una experiencia hermosa.","persona":"Diego Ferrer","ciudad":"Rosario"},{"id":"cita-3","frase":"Las tablas de Bruno son una locura. Ya le encargué tres para el restó y todas distintas.","persona":"Cecilia Nardi","ciudad":"Villa Allende"}]},{"type":"visita-taller","eyebrow":"Visitá el taller","filas":[{"id":"visita-1","label":"Taller","value":"Pasaje Los Álamos 240, Córdoba"},{"id":"visita-2","label":"Visitas","value":"Sáb de 10 a 14 hs, con aviso previo"},{"id":"visita-3","label":"WhatsApp","value":"0351 456-7890"},{"id":"visita-4","label":"Envíos","value":"A todo el país por correo o expreso"}],"imagen":"https://d38e2ri338t20n.cloudfront.net/uploads/8ed00373-2f35-4b9b-a20b-171563b96bba.jpg"},{"type":"footer","variant":"gigante"}]$manosbarro$::jsonb,
  $manosbarro${"nombreNegocio":"Manos de Barro","rubroLabel":"Cerámica · Telar · Madera","sobreNosotros":"Taller colectivo de tres artesanas en Córdoba: cerámica, telar y madera, todo hecho a mano.","whatsapp":"5493514567890","telefono":"0351 456-7890","direccion":"Pasaje Los Álamos 240, Córdoba","horarios":"Sáb de 10 a 14 hs, con aviso previo","galeria":["https://d38e2ri338t20n.cloudfront.net/uploads/8f1df357-27df-47ad-aedd-c39b1a9e1bdd.jpg","https://d38e2ri338t20n.cloudfront.net/uploads/24fba839-00ac-42e2-b60f-2d5a56838a79.jpg"]}$manosbarro$::jsonb,
  $manosbarro${"productos":[{"id":"prod-1","nombre":"Bowl esmaltado a mano","categoria":"Cerámica","desc":"Torneado y esmaltado uno por uno por Rosa, con la variación de color propia del horno a leña.","precio":"$34.000","etiqueta":"Última unidad","imagenes":["https://d38e2ri338t20n.cloudfront.net/uploads/14d89db4-b254-4321-afc7-0ad98962ce13.jpg"]},{"id":"prod-2","nombre":"Manta de telar patagónico","categoria":"Telar","desc":"Lana de oveja hilada y teñida por Amparo con tintes naturales, tejida en telar de pie durante seis semanas.","precio":"$128.000","etiqueta":"3 disponibles","imagenes":["https://d38e2ri338t20n.cloudfront.net/uploads/2b25a01b-dc1c-4a00-ba55-fa9e1a4aa883.jpg"]},{"id":"prod-3","nombre":"Tabla de algarrobo","categoria":"Madera","desc":"Algarrobo macizo de descarte, lijado a mano por Bruno y terminado con aceite de lino.","precio":"$46.000","etiqueta":"5 disponibles","imagenes":["https://d38e2ri338t20n.cloudfront.net/uploads/969cf1e8-030c-413f-a70a-d04232f5ad85.jpg"]},{"id":"prod-4","nombre":"Set de hilados teñidos","categoria":"Telar","desc":"Ovillos teñidos por Amparo en pequeñas tandas con cáscaras y raíces del monte cordobés.","precio":"$22.000","etiqueta":"8 disponibles","imagenes":["https://d38e2ri338t20n.cloudfront.net/uploads/ae06cd2a-9608-4467-85b3-e4afba396a7d.jpg"]},{"id":"prod-5","nombre":"Juego de cazuelas de barro","categoria":"Cerámica","desc":"Seis cazuelas torneadas por Rosa en tanda, secando al aire antes de entrar al horno.","precio":"$62.000","etiqueta":"4 disponibles","imagenes":["https://d38e2ri338t20n.cloudfront.net/uploads/7f1d2b79-d690-4dc7-ae45-15669564a93e.jpg"]},{"id":"prod-6","nombre":"Muestrario de tintes","categoria":"Telar","desc":"Cartilla armada por Amparo con las cincuenta tonalidades que saca de plantas de la zona.","precio":"$15.000","etiqueta":"12 disponibles","imagenes":["https://d38e2ri338t20n.cloudfront.net/uploads/24fba839-00ac-42e2-b60f-2d5a56838a79.jpg"]},{"id":"prod-7","nombre":"Vasija de gres","categoria":"Cerámica","desc":"Gres quemado a alta temperatura por Rosa, esmalte mate en el exterior y brillante por dentro.","precio":"$41.000","etiqueta":"2 disponibles","imagenes":["https://d38e2ri338t20n.cloudfront.net/uploads/4b7d78c2-ed5a-455b-a2f9-b32bcbcf340a.jpg"]}]}$manosbarro$::jsonb,
